from pandas import date_range
from pandas.errors import OutOfBoundsDatetime

# Try converting date_range to nanosecond periods for out-of-bounds date
try:
    result = date_range('2300-01-01', periods=2, freq='D', unit='s').to_period('ns')
    # If we get here, it didn't raise - record the first year
    if len(result) > 0:
        probe('date_range_to_period_ns_year_0', result[0].year)
        probe('date_range_to_period_ns_ordinal_0', result[0].ordinal)
except OutOfBoundsDatetime as e:
    probe('date_range_to_period_ns_raised', 1)
except Exception as e:
    probe('date_range_to_period_ns_exception', type(e).__name__)

